import React, { useEffect, useState } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";

const ViewTasks = () => {
  const user = JSON.parse(localStorage.getItem("users"));
  const [student, setStudent] = useState(null);
  const [group, setGroup] = useState(null);
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState({});
  const [newMilestone, setNewMilestone] = useState("");
  const [newTask, setNewTask] = useState({ title: "", creator: "", status: "Pending" });

  useEffect(() => {
    const fetchData = async () => {
      try {
        // 1. Get student by user ID
        const studentRes = await axios.get(`http://localhost:5000/api/student/${user.id}`);
        const studentData = studentRes.data;
        setStudent(studentData);

        if (!studentData.isGrouped) return;

        // 2. Get group by regNo
        const groupRes = await axios.get(`http://localhost:5000/api/group/byRegNo/${studentData.regNo}`);
        const groupData = groupRes.data;
        setGroup(groupData);

        // 3. Get milestones by groupNo
        const milestoneRes = await axios.get(`http://localhost:5000/api/milestone/groupNo/${groupData.groupNo}`);
        const milestonesData = milestoneRes.data;
        setMilestones(milestonesData);

        // 4. Get tasks per milestone
        const taskMap = {};
        for (const milestone of milestonesData) {
          const taskRes = await axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`);
          taskMap[milestone._id] = taskRes.data;
        }
        setTasks(taskMap);
      } catch (err) {
        console.error("Error loading data", err);
      }
    };

    fetchData();
  }, []);

  const handleAddMilestone = async () => {
    if (!newMilestone.trim() || !group) return;

    try {
      const res = await axios.post("http://localhost:5000/api/milestone", {
        title: newMilestone,
        dueDate: new Date(),
        projectID: group.projectID,
        status: "Ongoing",
      });
      const newMile = res.data;
      setMilestones([...milestones, newMile]);
      setNewMilestone("");
    } catch (err) {
      console.error("Error adding milestone", err);
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim() || !newTask.creator.trim()) return;

    try {
      const res = await axios.post("http://localhost:5000/api/task", {
        title: newTask.title,
        milestoneId: milestoneId,
        status: newTask.status,
        uploadedBy: student.studentName,
      });
      const task = res.data;
      setTasks({
        ...tasks,
        [milestoneId]: [...(tasks[milestoneId] || []), task],
      });
      setNewTask({ title: "", creator: "", status: "Pending" });
    } catch (err) {
      console.error("Error adding task", err);
    }
  };

  const handleUpdateTaskStatus = async (milestoneId, taskId) => {
    try {
      await axios.patch(`http://localhost:5000/api/task/${taskId}`, {
        status: "Completed",
        completedBy: student.studentName,
      });

      setTasks((prev) => ({
        ...prev,
        [milestoneId]: prev[milestoneId].map((task) =>
          task._id === taskId ? { ...task, status: "Completed", completedBy: student.studentName } : task
        ),
      }));
    } catch (err) {
      console.error("Error updating task", err);
    }
  };

  if (!student) return <div>Loading...</div>;
  if (!student.isGrouped) return <div>You are not part of a group yet.</div>;

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          <div className="milestone-section">
            <input
              type="text"
              value={newMilestone}
              onChange={(e) => setNewMilestone(e.target.value)}
              placeholder="Add a new milestone"
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due: {new Date(milestone.dueDate).toLocaleDateString()}</p>

                <div className="task-section">
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    placeholder="Task title"
                  />
                  <input
                    type="text"
                    value={newTask.creator}
                    onChange={(e) => setNewTask({ ...newTask, creator: e.target.value })}
                    placeholder="Created by"
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone._id)}>
                    Add Task
                  </button>

                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Creator</th>
                          <th>Status</th>
                          <th>Completed By</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(tasks[milestone._id] || []).map((task) => (
                          <tr key={task._id}>
                            <td>{task.title}</td>
                            <td>{task.uploadedBy}</td>
                            <td>{task.status}</td>
                            <td>{task.completedBy || "N/A"}</td>
                            <td>
                              {task.status !== "Completed" && (
                                <button
                                  className="mark-completed-button"
                                  onClick={() => handleUpdateTaskStatus(milestone._id, task._id)}
                                >
                                  Mark as Completed
                                </button>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
